CREATE EXTENSION IF NOT EXISTS vector;
DO $$ BEGIN CREATE TYPE book_status AS ENUM ('uploaded','parsing','chunking','embedding','ready','failed'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE book_format AS ENUM ('epub','pdf'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE message_role AS ENUM ('user','assistant','system'); EXCEPTION WHEN duplicate_object THEN null; END $$;
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS books (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, title text NOT NULL, author text NOT NULL, language text NOT NULL DEFAULT 'en', description text, format book_format NOT NULL DEFAULT 'epub', cover_storage_key text, original_storage_key text NOT NULL, status book_status NOT NULL DEFAULT 'uploaded', processing_progress integer NOT NULL DEFAULT 0, processing_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS books_owner_idx ON books(owner_id);
CREATE TABLE IF NOT EXISTS chapters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, spine_index integer NOT NULL, href text NOT NULL, title text NOT NULL, start_block_index integer NOT NULL, end_block_index integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(book_id, spine_index));
CREATE TABLE IF NOT EXISTS book_blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, chapter_id uuid NOT NULL REFERENCES chapters(id) ON DELETE CASCADE, spine_index integer NOT NULL, block_index integer NOT NULL, block_type text NOT NULL, heading_path jsonb NOT NULL DEFAULT '[]', text text NOT NULL, locator jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(book_id, spine_index, block_index));
CREATE TABLE IF NOT EXISTS book_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, chapter_id uuid NOT NULL REFERENCES chapters(id) ON DELETE CASCADE, ordinal integer NOT NULL, spine_index integer NOT NULL, start_block_index integer NOT NULL, end_block_index integer NOT NULL, heading_path jsonb NOT NULL DEFAULT '[]', text text NOT NULL, locator_start jsonb NOT NULL, locator_end jsonb NOT NULL, embedding vector(1536), search_text tsvector GENERATED ALWAYS AS (to_tsvector('english', text)) STORED, token_count integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(book_id, ordinal));
CREATE INDEX IF NOT EXISTS chunks_scope_idx ON book_chunks(book_id, spine_index, end_block_index);
CREATE INDEX IF NOT EXISTS chunks_search_idx ON book_chunks USING gin(search_text);
CREATE INDEX IF NOT EXISTS chunks_embedding_idx ON book_chunks USING hnsw (embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS reading_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, locator jsonb NOT NULL, spine_index integer NOT NULL, block_index integer NOT NULL, percentage real NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id, book_id));
CREATE TABLE IF NOT EXISTS highlights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, chapter_id uuid REFERENCES chapters(id) ON DELETE SET NULL, color text NOT NULL DEFAULT 'ochre', exact text NOT NULL, prefix text NOT NULL DEFAULT '', suffix text NOT NULL DEFAULT '', locator jsonb NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS highlights_owner_book_idx ON highlights(owner_id, book_id);
CREATE TABLE IF NOT EXISTS threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES threads(id) ON DELETE CASCADE, role message_role NOT NULL, parts jsonb NOT NULL, action text, scope text, current_locator jsonb, citations jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, book_id uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE, model text NOT NULL, action text NOT NULL, input_tokens integer, output_tokens integer, latency_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
